// Сводит ответы AmoCRM в контракт, который ждёт Shumm.
// Идентификаторы статусов берутся из узла «Настройки».
const cfg = $('Настройки').first().json;
const leadsRaw = $('Сделки за месяц').all();
const usersRaw = $('Менеджеры').all();

const leads = leadsRaw.flatMap(i => i.json?._embedded?.leads ?? []);
const users = usersRaw.flatMap(i => i.json?._embedded?.users ?? []);

const WON = 142; // системный статус «успешно реализовано»

const quals = leads.filter(l => l.status_id === cfg.qualStatusId).length || leads.length;
const measures = leads.filter(l => l.status_id === cfg.measureStatusId).length;
const contracts = leads.filter(l => l.status_id === WON).length;
const done = leads.filter(l => l.status_id === WON).reduce((s, l) => s + (l.price || 0), 0);

const byUser = {};
for (const l of leads) {
  const id = l.responsible_user_id;
  byUser[id] = byUser[id] || { total: 0, won: 0 };
  byUser[id].total++;
  if (l.status_id === WON) byUser[id].won++;
}
const initials = (name = '') => name.split(' ').filter(Boolean).slice(0, 2).map(p => p[0].toUpperCase() + '.').join(' ');
const managers = users.map(u => {
  const s = byUser[u.id] || { total: 0, won: 0 };
  return { name: initials(u.name), area: '', pct: s.total ? Math.round(s.won / s.total * 100) : 0 };
}).filter(m => m.name).sort((a, b) => b.pct - a.pct);

const HOUR = 3600;
const now = Math.floor(Date.now() / 1000);
const problems = leads
  .filter(l => l.status_id !== WON && now - (l.updated_at || l.created_at || now) > 48 * HOUR)
  .sort((a, b) => (a.updated_at || 0) - (b.updated_at || 0))
  .slice(0, 5)
  .map(l => ({
    id: String(l.id),
    title: l.name || ('Сделка №' + l.id),
    note: 'без касания',
    age: Math.round((now - (l.updated_at || now)) / HOUR) + ' ч',
    level: 'bad'
  }));

return [{
  json: {
    updated: new Date().toISOString(),
    plan: { target: cfg.planTarget, done },
    conversion: {
      current: quals ? Math.round(measures / quals * 100) : 0,
      goal: cfg.convGoal,
      deadline: cfg.convDeadline,
      history: []
    },
    funnel: { quals, measures, contracts },
    managers,
    problems
  }
}];
